def _validate_request(data, signature):
    """Validate the request payload and its signature.

    Payload validation is kept separate from processing so an invalid request
    cannot reach ``process``.  Signature verification is required for every
    request.
    """
    if data is None:
        raise ValueError("request data is required")

    if signature is None or signature == "" or signature == b"":
        raise PermissionError("invalid signature")

    if not verify_signature(data, signature):
        raise PermissionError("invalid signature")


def handle_request(data, signature):
    """Validate a signed request and process its payload."""
    _validate_request(data, signature)
    return process(data)

